import { For, type JSX } from "solid-js";
import { Box, Group, List, ListItem, Stack, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { fmtMoney } from "../utils";
import type { CtaContent } from "../blocks/cta-proof.types";

export type CtaProofItemsProps = {
  content: CtaContent;
  proof?: "logos" | "features" | "stats" | "rows" | "zones";
  center?: boolean;
};

export function CtaProofItems({ content, proof = "stats", center = false }: CtaProofItemsProps) {
